/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Constants: guard, noIdentifiers
 * Tests
 *   - a review binds one identity per member without upload evidence, so it is never stale, and its digest binds member IDs and media evidence
 *   - the shown primary Artist names come from the capture in stored order, a name repeated in another case once, never a featured, label or unshown Credit
 *   - member evidence keeps manifest order, exact and legacy durations, own numbers but never automatic ones, the primary names as artist tags and no identifiers
 *   - member evidence is total on malformed stored captures, drafts and origins
 *   - a review run is planned from the captured Album title and first usable primary name, or the submitted text with those names
 *   - a review's submitted Artist name is kept with the run and credits its searches in place of the primary names, never the members' artist evidence
 *   - only a review compares in subset mode
 * @end-catalog */

/**
 * An existing-Album review's metadata lookup inputs without a database: the members a run binds, each member's ranking evidence,
 * the shown primary Artist names and the run plan. All names and identifiers are synthetic.
 */
import assert from 'node:assert/strict';
import { after, test } from 'node:test';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import {
    catalogReviewFileEvidence, catalogReviewLookupFileSet, catalogReviewPrimaryNames, isCatalogReviewLookup, lookupComparisonFor, planCatalogReviewLookup
} from '../../src/administration/lookup/lookupReviewEvidence';
import { lookupStaleSlots } from '../../src/administration/lookup/metadataLookupRecord';
import { numberedMembers, reviewLookupDocument, reviewSlot, reviewTrackId } from '../support/catalogReviewLookupFixtures';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const noIdentifiers = { releaseId: null, barcode: null, catalogNumber: null };

test('a review binds one identity per member without upload evidence, so it is never stale, and its digest binds member IDs and media evidence', () => {
    const doc = reviewLookupDocument({ members: numberedMembers([200_000, 210_000, null]) });
    const set = catalogReviewLookupFileSet(doc);
    assert.deepEqual(set.files, [0, 1, 2].map(index => ({ slotId: reviewSlot(index), operationId: null, sha256: null })));
    assert.equal(set.complete, true);
    assert.equal(catalogReviewLookupFileSet(reviewLookupDocument({ members: numberedMembers([200_000, 210_000, null]) })).digest, set.digest);
    // Other media evidence or another member changes the digest; durations and titles do not.
    const replaced = { ...doc, catalogEvidence: { ...doc.catalogEvidence, [reviewTrackId(1)]: 'evidence-replaced' } } as AdminImportDocument;
    assert.notEqual(catalogReviewLookupFileSet(replaced).digest, set.digest);
    assert.notEqual(catalogReviewLookupFileSet(reviewLookupDocument({ members: numberedMembers([200_000, 210_000]) })).digest, set.digest);
    assert.equal(catalogReviewLookupFileSet(reviewLookupDocument({ members: numberedMembers([1, 2, 3]) })).digest, set.digest);
    // No identity carries an upload, so no later file set makes one stale, whatever it holds.
    assert.deepEqual(lookupStaleSlots(set.files, []), []);
    assert.deepEqual(lookupStaleSlots(set.files, catalogReviewLookupFileSet(replaced).files), []);
    // An empty Album binds nothing and is still complete; malformed stored shapes are skipped.
    assert.deepEqual(catalogReviewLookupFileSet(reviewLookupDocument()).files, []);
    assert.equal(catalogReviewLookupFileSet(reviewLookupDocument()).complete, true);
    const malformed = { manifest: { rootLabel: '', files: [null, { slotId: 7 }, { slotId: reviewSlot(0) }] }, catalogSource: { tracks: [null, { id: 5 }] }, catalogEvidence: 'x' } as never;
    assert.deepEqual(catalogReviewLookupFileSet(malformed).files, [{ slotId: reviewSlot(0), operationId: null, sha256: null }]);
    assert.deepEqual(catalogReviewLookupFileSet({ manifest: null, catalogSource: null } as never).files, []);
});

test('the shown primary Artist names come from the capture in stored order, a name repeated in another case once, never a featured, label or unshown Credit', () => {
    const doc = reviewLookupDocument({ primaryNames: ['Synthetic Lead', ' Synthetic Second ', 'synthetic lead', ''] });
    assert.deepEqual(catalogReviewPrimaryNames(doc), ['Synthetic Lead', 'Synthetic Second']);
    const credits = (doc.catalogCapture!.album.credits ?? []).map(entry => ({ ...entry }));
    credits[1] = { ...credits[1], entryKey: null };
    credits[0] = { ...credits[0], subject: null };
    // An unshown Credit or one whose record is not ready names nothing, so the later spelling is the first usable one.
    assert.deepEqual(catalogReviewPrimaryNames({ catalogCapture: { ...doc.catalogCapture!, album: { ...doc.catalogCapture!.album, credits } } }), ['synthetic lead']);
    // A review not yet captured, or a capture this release cannot read, shows no name.
    for (const capture of [undefined, null, 'x', { album: null }, { album: { credits: 'x' } }, { album: { credits: [null, 3, { subjectType: 'artist', role: 'primary', entryKey: 'k', subject: { name: 4 } }] } }]) {
        assert.deepEqual(catalogReviewPrimaryNames({ catalogCapture: capture } as never), [], JSON.stringify(capture));
    }
});

test('member evidence keeps manifest order, exact and legacy durations, own numbers but never automatic ones, the primary names as artist tags and no identifiers', () => {
    const members = [{ durationMs: 200_000, discNumber: 1, trackNumber: 1 }, { durationMs: 211_000, legacy: true, discNumber: 2, trackNumber: 1 }, { trackNumber: 3 }];
    const doc = reviewLookupDocument({ primaryNames: ['Synthetic Ensemble', 'synthetic ensemble', 'Synthetic Duo'], members,
        origins: { [`tracks:${reviewSlot(1)}:discNumber`]: 'automatic', [`tracks:${reviewSlot(2)}:trackNumber`]: 'automatic', [`tracks:${reviewSlot(0)}:trackNumber`]: 'administrator' } });
    const tags = ['Synthetic Ensemble', 'Synthetic Duo'];
    assert.deepEqual(catalogReviewFileEvidence(doc), [
        { slotId: reviewSlot(0), order: 0, durationMs: 200_000, durationPrecisionMs: 0, discNumber: 1, trackNumber: 1, artistTags: tags, identifiers: noIdentifiers },
        // A number lookup wrote (automatic) never constrains pairing.
        { slotId: reviewSlot(1), order: 1, durationMs: 211_000, durationPrecisionMs: 1000, discNumber: null, trackNumber: 1, artistTags: tags, identifiers: noIdentifiers },
        // A member that captured no duration is unknown.
        { slotId: reviewSlot(2), order: 2, durationMs: null, durationPrecisionMs: 0, discNumber: null, trackNumber: null, artistTags: tags, identifiers: noIdentifiers }]);
    // A review not yet captured knows no duration or name; its own numbers still count.
    assert.deepEqual(catalogReviewFileEvidence(reviewLookupDocument({ members, capture: false })).map(file => [file.durationMs, file.discNumber, file.trackNumber, file.artistTags]),
        [[null, 1, 1, []], [null, 2, 1, []], [null, null, 3, []]]);
});

test('member evidence is total on malformed stored captures, drafts and origins', () => {
    const doc = reviewLookupDocument({ members: numberedMembers([200_000, 210_000]) });
    const capture = doc.catalogCapture as unknown as Record<string, unknown>;
    const variants: Partial<AdminImportDocument>[] = [
        { catalogCapture: { ...capture, members: [{ slotId: reviewSlot(0), duration: { durationMs: -5 } }, { slotId: reviewSlot(1), duration: { durationMs: 1.5, durationPrecisionMs: 7 } }] } as never },
        { catalogCapture: { ...capture, members: 'x' } as never },
        { draft: null as never }, { draft: { album: null, tracks: [null, 'x', { slotId: reviewSlot(0), discNumber: 'one', trackNumber: 0 }] } as never },
        { draftOrigins: 'x' as never }, { manifest: { rootLabel: '', files: 'x' } as never }
    ];
    for (const variant of variants) {
        const evidence = catalogReviewFileEvidence({ ...doc, ...variant } as AdminImportDocument);
        assert.ok(evidence.every(file => file.durationMs === null || Number.isSafeInteger(file.durationMs)), JSON.stringify(variant));
        assert.ok(evidence.every(file => file.discNumber === null || Number.isSafeInteger(file.discNumber)));
    }
    const bad = catalogReviewFileEvidence({ ...doc, ...variants[0] } as AdminImportDocument);
    assert.deepEqual(bad.map(file => [file.durationMs, file.durationPrecisionMs]), [[null, 0], [null, 0]]);
    assert.deepEqual(catalogReviewFileEvidence({ ...doc, ...variants[3] } as AdminImportDocument).map(file => [file.discNumber, file.trackNumber]), [[null, null], [null, null]]);
    assert.deepEqual(catalogReviewFileEvidence({ ...doc, ...variants[5] } as AdminImportDocument), []);
});

test('a review run is planned from the captured Album title and first usable primary name, or the submitted text with those names', () => {
    const doc = reviewLookupDocument({ title: 'Synthetic Album (2013 Remaster)', primaryNames: ['Various Artists', 'Synthetic Ensemble'], members: numberedMembers([200_000, 210_000]) });
    // The administrator's edited draft title is not the saved title.
    (doc.draft as { album: { title: string } }).album.title = 'Edited Title';
    const catalog = planCatalogReviewLookup(doc);
    assert.deepEqual(catalog.input, { trigger: 'catalog', submitted: null });
    assert.deepEqual(catalog.plan.queries.map(query => (query as { query: unknown }).query), [
        { release: 'Synthetic Album (2013 Remaster)', artist: 'Synthetic Ensemble' }, { release: 'Synthetic Album (2013 Remaster)' },
        { release: 'Synthetic Album', artist: 'Synthetic Ensemble' }, { release: 'Synthetic Album' }]);
    // No Track title or original filename is ever planned.
    const sent = JSON.stringify(catalog.plan.queries);
    for (const text of ['Synthetic Track', 'synthetic-1.flac', 'Edited Title', 'Synthetic Label', 'Synthetic Guest']) assert.equal(sent.includes(text), false, text);
    const submitted = planCatalogReviewLookup(doc, { submitted: { kind: 'song', text: 'Synthetic Song' } });
    assert.deepEqual(submitted.input, { trigger: 'submitted', submitted: { kind: 'song', text: 'Synthetic Song' } });
    assert.deepEqual(submitted.plan.queries.map(query => (query as { query: unknown }).query), [{ recording: 'Synthetic Song', artist: 'Synthetic Ensemble' }, { recording: 'Synthetic Song' }]);
    // A review without a readable source or capture plans nothing from them.
    assert.deepEqual(planCatalogReviewLookup({ ...doc, catalogSource: undefined } as AdminImportDocument).plan, { queries: [], rejected: 'empty' });
    assert.deepEqual(planCatalogReviewLookup({ ...doc, catalogCapture: undefined } as AdminImportDocument).plan.queries.map(query => (query as { query: unknown }).query),
        [{ release: 'Synthetic Album (2013 Remaster)' }, { release: 'Synthetic Album' }]);
});

test('a review\'s submitted Artist name is kept with the run and credits its searches in place of the primary names, never the members\' artist evidence', () => {
    const doc = reviewLookupDocument({ primaryNames: ['Synthetic Ensemble'], members: numberedMembers([200_000, 210_000]) });
    for (const kind of ['album', 'song'] as const) {
        const typed = planCatalogReviewLookup(doc, { submitted: { kind, text: 'Synthetic Typed Name', artist: 'Synthetic Typed' } });
        assert.deepEqual(typed.input, { trigger: 'submitted', submitted: { kind, text: 'Synthetic Typed Name', artist: 'Synthetic Typed' } });
        const field = kind === 'album' ? 'release' : 'recording';
        assert.deepEqual(typed.plan.queries.map(query => (query as { query: unknown }).query),
            [{ [field]: 'Synthetic Typed Name', artist: 'Synthetic Typed' }, { [field]: 'Synthetic Typed Name' }], kind);
        assert.equal(JSON.stringify(typed.plan).includes('Synthetic Ensemble'), false, kind);
    }
    // Another shape or one that cannot be sent is dropped, so the name is still searched and the primary names credit it again.
    for (const artist of [7, 'https://example.invalid/a']) {
        const malformed = planCatalogReviewLookup(doc, { submitted: { kind: 'album', text: 'Synthetic Typed Name', artist: artist as never } });
        assert.deepEqual(malformed.input, { trigger: 'submitted', submitted: { kind: 'album', text: 'Synthetic Typed Name' } }, String(artist));
        assert.deepEqual(malformed.plan.queries.map(query => (query as { query: unknown }).query),
            [{ release: 'Synthetic Typed Name', artist: 'Synthetic Ensemble' }, { release: 'Synthetic Typed Name' }], String(artist));
    }
    // The ranking's artist evidence stays the primary names: a typed Artist name is never evidence.
    assert.deepEqual(catalogReviewFileEvidence(doc).map(file => file.artistTags), [['Synthetic Ensemble'], ['Synthetic Ensemble']]);
});

test('only a review compares in subset mode', () => {
    assert.deepEqual([isCatalogReviewLookup({ purpose: 'catalogReview' }), lookupComparisonFor({ purpose: 'catalogReview' })], [true, 'subset']);
    for (const purpose of ['import', null, undefined] as const) assert.deepEqual([isCatalogReviewLookup({ purpose }), lookupComparisonFor({ purpose })], [false, 'exact']);
});
